(async()=>{
  const qs=s=>document.querySelector(s), qsa=s=>[...document.querySelectorAll(s)];
  const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const text=s=>esc(s).replace(/\n/g,'<br>');
  const fmt=d=>{if(!d)return'';const dt=new Date(d);return Number.isNaN(+dt)?esc(d):dt.toLocaleDateString('th-TH',{year:'numeric',month:'short',day:'numeric'})};
  const dateBits=d=>{if(!d)return{day:'',month:''};const dt=new Date(d);if(Number.isNaN(+dt))return{day:'',month:''};return{day:String(dt.getDate()).padStart(2,'0'),month:dt.toLocaleDateString('th-TH',{month:'short',year:'2-digit'})}};
  const safeUrl=u=>{try{const x=new URL(u,location.origin);return ['http:','https:'].includes(x.protocol)?x.href:'#'}catch{return '#'}};
  const safeLink=u=>{const v=String(u||'').trim(); if(!v)return'#'; if(/^[a-z0-9_-]+\.html(?:[?#].*)?$/i.test(v)||v.startsWith('/')||v.startsWith('#'))return esc(v); return safeUrl(v)};
  const media=u=>{const v=String(u||'').trim();if(!v)return'';if(v.startsWith('/assets/'))return v;if(v.startsWith('assets/'))return '/'+v;try{const x=new URL(v,location.origin);return ['http:','https:'].includes(x.protocol)?x.href:''}catch{return''}};
  const imageBlock=(src,alt='',cls='cms-section-image')=>{const u=media(src);return u?`<figure class=\"${cls} reveal\"><img src=\"${esc(u)}\" alt=\"${esc(alt||'ภาพประกอบ')}\" loading=\"lazy\"></figure>`:''};
  const heroBg=(src,alt='')=>{const u=media(src);return u?`<div class=\"hero-background-media\" aria-hidden=\"true\"><img src=\"${esc(u)}\" alt=\"${esc(alt)}\"></div>`:''};
  const val=(o,k,d='')=>o&&o[k]!==undefined&&o[k]!==null?o[k]:d;
  let data;
  try{const r=await fetch('/site-content.json',{cache:'no-store'});if(!r.ok)throw 0;data=await r.json()}
  catch{data={news:[],documents:[],announcements:[],gallery:[],sources:[],settings:{},pages:{}}}
  const settings=data.settings||{}, pages=data.pages||{}, page=document.body.dataset.page||'';

  // Global site settings.
  if(settings.association_name){qsa('.brand-text strong').forEach(el=>{if(!el.closest('.header-contact-item,.footer-emergency-box'))el.innerHTML=esc(settings.association_name).replace(' บรรเทาสาธารณภัย','<br>บรรเทาสาธารณภัย')})}
  if(settings.facebook){qsa('[data-site-facebook],a[href*="facebook.com/piyamitr.maesai"]').forEach(a=>a.href=safeUrl(settings.facebook))}
  if(settings.emergency){
    qsa('[data-site-emergency]').forEach(el=>el.textContent=settings.emergency);
    qsa('a[href="tel:1669"]').forEach(a=>a.href='tel:'+String(settings.emergency).replace(/\s/g,''));
  }
  if(settings.phone){
    qsa('[data-site-phone]').forEach(el=>el.textContent=settings.phone);
    qsa('[data-site-phone-wrap]').forEach(el=>{el.hidden=false;if(el.tagName==='A')el.href='tel:'+String(settings.phone).replace(/\s/g,'')});
    qsa('[data-site-phone-link]').forEach(a=>a.href='tel:'+String(settings.phone).replace(/\s/g,''));
  }
  if(settings.email){
    qsa('[data-site-email]').forEach(el=>el.textContent=settings.email);
    qsa('[data-site-email-wrap]').forEach(el=>el.hidden=false);
    qsa('[data-site-email-link]').forEach(a=>a.href='mailto:'+settings.email);
  }
  if(settings.line){qsa('[data-site-line]').forEach(el=>el.textContent=settings.line);qsa('[data-site-line-wrap]').forEach(el=>el.hidden=false)}
  if(settings.address){qsa('[data-site-address]').forEach(el=>el.textContent=settings.address)}
  if(settings.qr_image){
    qsa('[data-site-qr]').forEach(img=>img.src=media(settings.qr_image)||settings.qr_image);
    qsa('[data-site-qr-wrap]').forEach(el=>el.hidden=false);
  }

  const pageHero=(p,current)=>`<section class="page-hero ${p.hero_background?'has-hero-image':''}">${heroBg(p.hero_background,p.hero_title||current)}<div class="hero-grid-pattern" aria-hidden="true"></div><div class="container page-hero-layout"><div class="page-hero-inner reveal"><nav class="breadcrumb" aria-label="เส้นทางนำทาง"><a href="index.html">หน้าแรก</a><span>/</span><span aria-current="page">${esc(current)}</span></nav><p class="eyebrow">${esc(val(p,'hero_kicker','P.C.R.C.'))}</p><h1>${esc(val(p,'hero_title',current))}</h1><p>${text(val(p,'hero_intro',''))}</p></div><div class="page-hero-logo reveal"><img src="assets/piyamitr-logo.png" alt="ตราสัญลักษณ์ P.C.R.C."></div></div></section>`;
  const valueCards=items=>(items||[]).map((x,i)=>`<article class="value-card reveal"><span>${String(i+1).padStart(2,'0')}</span><h3>${esc(x.title)}</h3><p>${text(x.body)}</p></article>`).join('');

  const renderPage=()=>{
    const p=pages[page]; if(!p)return;
    if(p.hero_title) document.title=`${p.hero_title} | P.C.R.C.`;
    const main=qs('main#main'); if(!main)return;
    if(page==='home'){
      const statIcons=['☎','⌖','✚','f'];
      const stats=(p.stats||[]).slice(0,4).map((x,i)=>`<div class="stat-item"><span class="stat-icon stat-icon-${i}">${statIcons[i]||'•'}</span><span class="stat-copy"><small>${text(x.label)}</small><strong>${esc(x.value)}</strong></span></div>`).join('');
      const missionItems=((pages.missions&&pages.missions.missions)||[]).slice(0,4);
      const missionCards=missionItems.length?missionItems.map(x=>`<article class="mission-card home-mission-card reveal"><span>${esc(x.icon||'•')}</span><h3>${esc(x.title)}</h3><p>${text(x.body)}</p></article>`).join(''):`<article class="mission-card home-mission-card"><span>🚑</span><h3>กู้ชีพและช่วยเหลือ</h3><p>ช่วยเหลือผู้ประสบเหตุและประสานการนำส่งตามความเหมาะสม</p></article><article class="mission-card home-mission-card"><span>🔥</span><h3>บรรเทาสาธารณภัย</h3><p>สนับสนุนการช่วยเหลือเมื่อเกิดสาธารณภัย</p></article><article class="mission-card home-mission-card"><span>✚</span><h3>อบรมและให้ความรู้</h3><p>ส่งเสริมทักษะปฐมพยาบาลและช่วยชีวิตขั้นพื้นฐาน</p></article><article class="mission-card home-mission-card"><span>♥</span><h3>สาธารณกุศล</h3><p>ช่วยเหลือผู้ยากไร้และกิจกรรมเพื่อสังคม</p></article>`;
      main.innerHTML=`<section class="home-hero reference-home ${p.hero_background?'has-hero-image':''}">${heroBg(p.hero_background,p.hero_title)}<div class="hero-grid-pattern" aria-hidden="true"></div><div class="container home-hero-grid"><div class="hero-copy reveal"><p class="eyebrow">${esc(p.hero_eyebrow)}</p><h1>${esc(p.hero_title)}<br><span>${esc(p.hero_highlight)}</span></h1><p class="association-fullname">${esc(p.hero_fullname)}</p><p class="lead">${text(p.hero_intro)}</p><div class="hero-actions"><a class="btn btn-primary hero-help-btn" href="${safeLink(p.hero_primary_link)}"><span>♟</span>${esc(p.hero_primary_text)}</a><a class="btn btn-outline-light" href="${safeLink(p.hero_secondary_link)}"><span>♙</span>${esc(p.hero_secondary_text)}</a></div></div><div class="hero-visual reveal"><img class="hero-official-logo" src="assets/piyamitr-logo.png" alt="ตราสัญลักษณ์สมาคมปิยะมิตรแม่สายร่วมใจ"></div></div></section>
      <section class="stats-strip" aria-label="ข้อมูลสำคัญ"><div class="container stats-grid">${stats}</div></section>
      <section class="home-overview-section"><div class="container home-overview-grid"><div class="home-panel home-missions-panel"><div class="home-panel-heading"><h2>${esc(p.mission_title||'ภารกิจของเรา')}</h2><a href="missions.html">ดูทั้งหมด →</a></div><div class="mission-grid home-mission-grid">${missionCards}</div></div><div class="home-panel home-news-panel"><div class="home-panel-heading"><h2>${esc(p.latest_title||'ข่าวสารล่าสุด')}</h2><a href="news.html">ดูทั้งหมด →</a></div><div class="news-grid home-news-grid" data-latest-news><div class="news-loading">กำลังโหลดข่าว...</div></div></div></div></section>
      <section class="home-cta-section"><div class="container home-cta-band"><div class="home-cta-item"><span class="home-cta-icon">♟</span><div><h3>ร่วมเป็นส่วนหนึ่งของเรา</h3><p>สมัครเป็นอาสาสมัคร เพื่อร่วมช่วยเหลือเพื่อนมนุษย์และสังคม</p></div><a class="btn btn-navy" href="volunteer.html">สมัครอาสาสมัคร</a></div><div class="home-cta-divider"></div><div class="home-cta-item"><span class="home-cta-icon">♥</span><div><h3>ร่วมสนับสนุนการช่วยเหลือ</h3><p>ตรวจสอบช่องทางสนับสนุนที่สมาคมเผยแพร่อย่างเป็นทางการ</p></div><a class="btn btn-navy" href="donate.html">ร่วมบริจาค</a></div></div></section>`;
      return;
    }
    if(page==='about'){
      main.innerHTML=pageHero(p,'เกี่ยวกับเรา')+`<section class="section"><div class="container split align-center"><div class="section-copy reveal"><p class="section-kicker">${esc(p.section_kicker)}</p><h2>${esc(p.section_title)}</h2><p>${text(p.section_body)}</p><p class="notice">${text(p.notice)}</p></div><div class="cms-side-stack">${imageBlock(p.section_image,p.section_image_alt||p.section_title)}<aside class="info-card reveal"><img src="assets/piyamitr-logo.png" alt="ตราสัญลักษณ์ P.C.R.C."><h3>P.C.R.C.</h3><p>The Piyamitr Maesai Co-operative Emergency Rescue And Charity</p><dl><div><dt>พื้นที่หลัก</dt><dd>${esc(p.area)}</dd></div><div><dt>ลักษณะงาน</dt><dd>${esc(p.work_type)}</dd></div></dl></aside></div></div></section><section class="section section-soft"><div class="container"><div class="section-head reveal"><div><p class="section-kicker">${esc(p.values_kicker)}</p><h2>${esc(p.values_title)}</h2></div><p>${text(p.values_intro)}</p></div><div class="values-grid">${valueCards(p.values)}</div></div></section><section class="section"><div class="container"><div class="section-head reveal"><div><p class="section-kicker">${esc(p.timeline_kicker)}</p><h2>${esc(p.timeline_title)}</h2></div></div><ol class="timeline-wide">${(p.timeline||[]).map(x=>`<li class="reveal"><span>${esc(x.year)}</span><div><h3>${esc(x.title)}</h3><p>${text(x.body)}</p></div></li>`).join('')}</ol></div></section>`;
    }
    if(page==='missions'){
      main.innerHTML=pageHero(p,'ภารกิจ')+`<section class="section"><div class="container">${imageBlock(p.section_image,p.section_image_alt||p.hero_title,'cms-section-image cms-section-image-wide')}<div class="mission-grid">${(p.missions||[]).map(x=>`<article class="mission-card reveal"><span>${esc(x.icon)}</span><h3>${esc(x.title)}</h3><p>${text(x.body)}</p></article>`).join('')}</div></div></section><section class="section section-soft"><div class="container cta-band reveal"><div><p class="section-kicker">${esc(p.cta_kicker)}</p><h2>${esc(p.cta_title)}</h2><p>${text(p.cta_body)}</p></div><a class="btn btn-primary" href="volunteer.html">${esc(p.cta_button)}</a></div></section>`;
    }
    if(page==='news'){
      main.innerHTML=pageHero(p,'ข่าวสาร')+`<section class="section"><div class="container">${imageBlock(p.section_image,p.section_image_alt||p.news_title,'cms-section-image cms-section-image-wide')}<div class="section-head reveal"><div><p class="section-kicker">${esc(p.news_kicker)}</p><h2>${esc(p.news_title)}</h2></div><p>${text(p.news_intro)}</p></div><div class="news-grid" data-news-list><div class="news-loading">กำลังโหลดข่าว...</div></div></div></section><section class="section section-soft"><div class="container"><div class="section-head reveal"><div><p class="section-kicker">${esc(p.gallery_kicker)}</p><h2>${esc(p.gallery_title)}</h2></div><p>${text(p.gallery_intro)}</p></div><div class="album-grid" data-gallery-list><div class="news-loading">กำลังโหลดอัลบั้มภาพ...</div></div></div></section><section class="section section-soft"><div class="container cta-band reveal"><div><p class="section-kicker">${esc(p.cta_kicker)}</p><h2>${esc(p.cta_title)}</h2><p>${text(p.cta_body)}</p></div><a class="btn btn-primary" href="${safeUrl(settings.facebook||'https://www.facebook.com/piyamitr.maesai')}" target="_blank" rel="noopener noreferrer">${esc(p.cta_button)}</a></div></section>`;
    }
    if(page==='volunteer'){
      main.innerHTML=pageHero(p,'อาสาสมัคร')+`<section class="section"><div class="container split align-center"><div class="section-copy reveal"><p class="section-kicker">${esc(p.section_kicker)}</p><h2>${esc(p.section_title)}</h2><p>${text(p.section_body)}</p><div class="tags">${(p.roles||[]).map(x=>`<span>${esc(x)}</span>`).join('')}</div></div><div class="cms-side-stack">${imageBlock(p.section_image,p.section_image_alt||p.section_title)}<aside class="info-card contact-card reveal"><img src="assets/piyamitr-logo.png" alt="โลโก้ P.C.R.C."><h3>${esc(p.contact_title)}</h3><p>${text(p.contact_body)}</p><a class="btn btn-primary btn-block" href="${safeUrl(settings.facebook||'https://www.facebook.com/piyamitr.maesai')}" target="_blank" rel="noopener noreferrer">${esc(p.contact_button)}</a></aside></div></div></section><section class="section section-soft"><div class="container"><div class="section-head reveal"><div><p class="section-kicker">${esc(p.qualities_kicker)}</p><h2>${esc(p.qualities_title)}</h2></div></div><div class="values-grid">${valueCards(p.qualities)}</div></div></section>`;
    }
    if(page==='donate'){
      main.innerHTML=pageHero(p,'ร่วมบริจาค')+`<section class="section"><div class="container">${imageBlock(p.section_image,p.section_image_alt||p.section_title,'cms-section-image cms-section-image-wide')}<div class="donate-page-grid"><div class="section-copy reveal"><p class="section-kicker">${esc(p.section_kicker)}</p><h2>${esc(p.section_title)}</h2><p>${text(p.section_body)}</p><ul class="check-list light-list">${(p.safety||[]).map(x=>`<li><strong>${esc(x.title)}</strong><span>${text(x.body)}</span></li>`).join('')}</ul><a class="btn btn-primary" href="${safeUrl(settings.facebook||'https://www.facebook.com/piyamitr.maesai')}" target="_blank" rel="noopener noreferrer">ตรวจสอบกับ Facebook สมาคม ↗</a></div><div data-donation-cms><aside class="safe-box reveal"><div class="shield">✓</div><h3>กำลังตรวจสอบข้อมูล</h3><p>กำลังโหลดช่องทางสนับสนุนที่ผู้ดูแลเผยแพร่</p></aside></div></div></div></section><section class="section section-soft"><div class="container"><div class="section-head reveal"><div><p class="section-kicker">${esc(p.support_kicker)}</p><h2>${esc(p.support_title)}</h2></div><p>${text(p.support_intro)}</p></div><div class="support-grid">${(p.support_items||[]).map(x=>`<div class="support-card reveal"><span>${esc(x.icon)}</span><h3>${esc(x.title)}</h3><p>${text(x.body)}</p></div>`).join('')}</div></div></section>`;
    }
    if(page==='downloads'){
      main.innerHTML=pageHero(p,'ดาวน์โหลด')+`<section class="section"><div class="container">${imageBlock(p.section_image,p.section_image_alt||p.hero_title,'cms-section-image cms-section-image-wide')}<div class="notice-large reveal"><strong>${esc(p.status_title)}</strong><p>${text(p.status_body)}</p></div><div class="download-list" data-documents-list><div class="news-loading">กำลังโหลดเอกสาร...</div></div></div></section><section class="section section-soft"><div class="container cta-band reveal"><div><p class="section-kicker">${esc(p.cta_kicker)}</p><h2>${esc(p.cta_title)}</h2><p>${text(p.cta_body)}</p></div><a class="btn btn-primary" href="contact.html">${esc(p.cta_button)}</a></div></section>`;
    }
    if(page==='contact'){
      main.innerHTML=pageHero(p,'ติดต่อเรา')+`<section class="section"><div class="container contact-page-grid"><div class="contact-stack" data-contact-cms><div class="news-loading">กำลังโหลดช่องทางติดต่อ...</div></div><div class="map-card reveal ${p.section_image?'has-map-image':''}">${p.section_image?`<img class="map-photo" src="${esc(media(p.section_image))}" alt="${esc(p.section_image_alt||p.map_label||'ภาพสถานที่')}">`:'<div class="map-grid-bg"></div>'}<div class="map-center">⌖<span>${esc(p.map_label)}</span></div><div class="map-note">${text(p.map_note)}</div></div></div></section><section class="section section-soft"><div class="container"><div class="notice-large reveal"><strong>${esc(p.notice_title)}</strong><p>${text(p.notice_body)}</p></div></div></section>`;
    }
  };
  renderPage();

  qsa('[data-announcements]').forEach(el=>{const today=new Date().toISOString().slice(0,10);const items=(data.announcements||[]).filter(x=>(!x.start||x.start<=today)&&(!x.end||x.end>=today));el.innerHTML=items.length?items.map(x=>`<article class="announcement-card ${esc(x.level)}"><h3>${esc(x.title)}</h3><p>${text(x.body)}</p></article>`).join(''):''});
  const newsCard=x=>{const d=dateBits(x.date);return `<article class="news-card">${x.cover?`<div class="news-thumb"><img src="${esc(x.cover)}" alt="${esc(x.title)}" loading="lazy">${d.day?`<span class="news-date-badge"><b>${d.day}</b><small>${esc(d.month)}</small></span>`:''}</div>`:`<div class="news-thumb news-placeholder"><img src="assets/piyamitr-logo.png" alt="" loading="lazy">${d.day?`<span class="news-date-badge"><b>${d.day}</b><small>${esc(d.month)}</small></span>`:''}</div>`}<div class="news-card-body"><div class="news-meta"><span class="pill">${esc(x.category||'ข่าวสาร')}</span></div><h3><a href="news-detail.html?slug=${encodeURIComponent(x.slug)}">${esc(x.title)}</a></h3><p>${text(x.summary||'')}</p><a class="news-readmore" href="news-detail.html?slug=${encodeURIComponent(x.slug)}">อ่านต่อ →</a></div></article>`};
  qsa('[data-news-list]').forEach(el=>el.innerHTML=data.news?.length?data.news.map(newsCard).join(''):'<div class="empty-state">ยังไม่มีข่าวที่เผยแพร่</div>');
  qsa('[data-latest-news]').forEach(el=>el.innerHTML=data.news?.length?data.news.slice(0,3).map(newsCard).join(''):'<div class="empty-state">ยังไม่มีข่าวที่เผยแพร่</div>');
  qsa('[data-documents-list]').forEach(el=>{el.innerHTML=data.documents?.length?data.documents.map(x=>`<article class="download-item"><div><div class="download-meta">${esc(x.category||'เอกสาร')} • ${fmt(x.date)}</div><h3>${esc(x.title)}</h3><p>${text(x.description||'')}</p></div><a class="btn btn-primary" href="${esc(x.file||'#')}" target="_blank" rel="noopener">ดาวน์โหลด</a></article>`).join(''):'<div class="empty-state">ยังไม่มีเอกสารที่เผยแพร่</div>'});
  qsa('[data-gallery-list]').forEach(el=>{el.innerHTML=data.gallery?.length?data.gallery.map(x=>{const cover=x.cover||x.images?.[0]||'';return `<article class="album-card">${cover?`<img src="${esc(cover)}" alt="${esc(x.title)}" loading="lazy">`:''}<div class="album-card-body"><div class="news-meta">${fmt(x.date)} • ${(x.images||[]).length} ภาพ</div><h3>${esc(x.title)}</h3><p>${text(x.description||'')}</p></div></article>`}).join(''):'<div class="empty-state">ยังไม่มีอัลบั้มภาพที่เผยแพร่</div>'});
  qsa('[data-contact-cms]').forEach(el=>{const rows=[];if(settings.phone)rows.push(['โทรศัพท์',`<a href="tel:${esc(String(settings.phone).replace(/\s/g,''))}">${esc(settings.phone)}</a>`]);if(settings.email)rows.push(['อีเมล',`<a href="mailto:${esc(settings.email)}">${esc(settings.email)}</a>`]);if(settings.line)rows.push(['LINE',esc(settings.line)]);if(settings.address)rows.push(['ที่อยู่',esc(settings.address)]);if(settings.map_url)rows.push(['แผนที่',`<a href="${safeUrl(settings.map_url)}" target="_blank" rel="noopener">เปิดแผนที่ ↗</a>`]);if(settings.facebook)rows.push(['Facebook',`<a href="${safeUrl(settings.facebook)}" target="_blank" rel="noopener">เปิดเพจสมาคม ↗</a>`]);el.innerHTML=rows.length?rows.map(r=>`<article class="contact-card"><strong>${r[0]}</strong><div>${r[1]}</div></article>`).join(''):'<div class="notice-large">ข้อมูลติดต่ออยู่ระหว่างการตรวจสอบ กรุณาติดต่อผ่าน Facebook ของสมาคม</div>'});
  qsa('[data-donation-cms]').forEach(el=>{if(settings.donate_enabled&&settings.account_name&&settings.account_number){el.innerHTML=`<aside class="safe-box donation-data"><div class="shield">฿</div><h3>ช่องทางสนับสนุนที่เผยแพร่</h3>${settings.bank_name?`<p><strong>ธนาคาร:</strong> ${esc(settings.bank_name)}</p>`:''}<p><strong>ชื่อบัญชี:</strong> ${esc(settings.account_name)}</p><p><strong>เลขบัญชี</strong></p><div class="account">${esc(settings.account_number)}</div>${settings.qr_image?`<img class="donation-qr" src="${esc(settings.qr_image)}" alt="QR Code บริจาค">`:''}<p>${text(settings.donation_note||'')}</p></aside>`}else{el.innerHTML='<aside class="safe-box"><div class="shield">✓</div><h3>โปรดตรวจสอบช่องทางทางการ</h3><p>ยังไม่ได้เปิดเผยข้อมูลบัญชีผ่านระบบเว็บไซต์ กรุณาตรวจสอบกับ Facebook ของสมาคมก่อนบริจาค</p></aside>'}});
  const detail=qs('[data-news-detail]');if(detail){const slug=new URLSearchParams(location.search).get('slug');const x=(data.news||[]).find(n=>n.slug===slug);if(!x){detail.innerHTML='<div class="empty-state">ไม่พบข่าวนี้ หรือข่าวยังไม่ได้เผยแพร่</div>'}else{document.title=`${x.title} | P.C.R.C.`;detail.innerHTML=`<article class="news-article"><div class="news-meta"><span class="pill">${esc(x.category||'ข่าวสาร')}</span><span>${fmt(x.date)}</span>${x.location?`<span>• ${esc(x.location)}</span>`:''}</div><h1>${esc(x.title)}</h1><p class="lead" style="color:#536476">${text(x.summary||'')}</p>${x.cover?`<img class="news-cover" src="${esc(x.cover)}" alt="${esc(x.title)}">`:''}<div class="article-body">${text(x.body||'')}</div>${x.images?.length?`<div class="article-gallery">${x.images.map(i=>`<img src="${esc(i)}" alt="ภาพประกอบ ${esc(x.title)}" loading="lazy">`).join('')}</div>`:''}${x.source_url?`<div class="source-box"><strong>แหล่งข้อมูล:</strong> ${esc(x.source_name||x.source_url)}<br><a href="${safeUrl(x.source_url)}" target="_blank" rel="noopener noreferrer">เปิดแหล่งข้อมูลต้นทาง ↗</a></div>`:''}</article>`}}
})();
